mapper.select:
SELECT 
  FROM tb_service v
 WHERE v.server_id = #{serverId}
   AND v.svc_nm    = #{svcNm}

SELECT 
  FROM tb_service v
 WHERE v.svc_id = #{svcId}

SELECT COALESCE(MAX(v.list_no), 0)
  FROM tb_service v
 WHERE v.server_id = #{serverId}

mapper.update:
UPDATE tb_service
   SET list_no = #{listNo}
 WHERE svc_id = #{svcId}

UPDATE tb_service
   SET state_cd = #{stateCd},
       pid      = #{pid, jdbcType=INTEGER},
       state_dt = CURRENT_TIMESTAMP
 WHERE server_id = #{serverId}
   AND svc_nm    = #{svcNm}

mapper.insert:
INSERT INTO tb_service_metric_hist (svc_id, server_id, collect_dt, cpu_pct, mem_pct, running_yn)
SELECT v.svc_id, v.server_id, CURRENT_TIMESTAMP,
       #{cpuPct, jdbcType=DECIMAL}, #{memPct, jdbcType=DECIMAL}, #{runningYn}
  FROM tb_service v
 WHERE v.server_id = #{serverId}
   AND v.svc_nm    = #{svcNm}

mapper.delete:
DELETE FROM tb_service_metric_hist
 WHERE server_id = #{serverId}
   AND collect_dt < #{before}

mapper.select:
SELECT 
  FROM tb_service_cmd c
 WHERE c.server_id = #{serverId}
   AND c.cmd_id    = #{cmdId}

choose.when:
SELECT TOP ${rows} 
  FROM tb_service_cmd c
 WHERE c.server_id = #{serverId}
 ORDER BY c.cmd_id DESC

SELECT TOP ${rows} 
  FROM tb_service_cmd c
 WHERE c.server_id = #{serverId}
   AND c.target IN
   #{t}
 ORDER BY c.cmd_id DESC

choose.otherwise:
SELECT t.cmd_id, t.server_id, t.target, t.cmd_cd, t.state_cd, t.req_user, t.req_dt, t.sent_dt, t.end_dt, t.exit_cd, t.result_msg
  FROM (SELECT ,
               ROW_NUMBER() OVER (ORDER BY c.cmd_id DESC) AS rn
          FROM tb_service_cmd c
         WHERE c.server_id = #{serverId}
           AND c.target IN
           #{t}
       ) t
 WHERE t.rn <= #{rows}
 ORDER BY t.cmd_id DESC
